pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner1, address _owner2) public {
        vm.assume(_owner1 != _owner2);
        address admin = address(this);
        vm.prank(admin);
        c.setOwner(_owner1);
        vm.prank(admin);
        c.setOwner(_owner2);
        assertTrue(c.owner() == _owner2);
    }
}
